using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

namespace ngakamodirimolema
{
    public partial class ServiceRequestStatusForm : Form
    {
        private readonly ServiceRequestService _service = ServiceRequestRepository.Service;
        private ServiceRequest? _selected;
        public ServiceRequestStatusForm() { InitializeComponent(); ApplyModernStyling(); InitializeFilters(); LoadRequests(_service.GetAll()); BuildCategoryTree(); txtInsights.Text = _service.Insights(); }
        private void ApplyModernStyling()
        {
            Font = new Font("Segoe UI", 9F); var teal=Color.FromArgb(0,150,136); BackColor=Color.White; dgvRequests.BackgroundColor=Color.White; dgvRequests.BorderStyle=BorderStyle.None; dgvRequests.EnableHeadersVisualStyles=false; dgvRequests.RowHeadersVisible=false; dgvRequests.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(250,250,250); dgvRequests.ColumnHeadersDefaultCellStyle.BackColor=teal; dgvRequests.ColumnHeadersDefaultCellStyle.ForeColor=Color.White; dgvRequests.ColumnHeadersDefaultCellStyle.Font=new Font(Font,FontStyle.Bold); dgvRequests.DefaultCellStyle.SelectionBackColor=Color.FromArgb(200,240,235); dgvRequests.DefaultCellStyle.SelectionForeColor=Color.Black; dgvRequests.RowTemplate.Height=32;
            foreach(var b in new[]{btnFilter,btnTrack,btnAdvance,btnUrgent,btnProcess,btnRelated,btnRoute,btnSelfCheck}) { b.FlatStyle=FlatStyle.Flat; b.FlatAppearance.BorderSize=0; b.BackColor=teal; b.ForeColor=Color.White; b.Cursor=Cursors.Hand; }
            btnClear.FlatStyle=FlatStyle.Flat; btnClear.BackColor=Color.White; btnClear.ForeColor=teal; btnClear.FlatAppearance.BorderColor=teal;
        }
        private void InitializeFilters() { cmbStatus.Items.Add("All"); cmbStatus.Items.AddRange(Enum.GetNames<ServiceRequestStatus>()); cmbStatus.SelectedIndex=0; cmbCategory.Items.Add("All"); cmbCategory.Items.AddRange(new[]{"Road","Water","Electricity","Sanitation","Other"}); cmbCategory.SelectedIndex=0; }
        private void LoadRequests(System.Collections.Generic.IEnumerable<ServiceRequest> requests) { var list=requests.ToList(); dgvRequests.DataSource=list.Select(r=>new { r.RequestId,r.Title,r.Category,r.Location,Priority=r.Priority.ToString(),Status=r.Status.ToString(),Submitted=r.SubmittedAt.ToString("dd/MM/yyyy"),Updated=r.UpdatedAt.ToString("dd/MM/yyyy") }).ToList(); lblEmpty.Visible=list.Count==0; }
        private void BuildCategoryTree() { treeCategories.Nodes.Clear(); var root=treeCategories.Nodes.Add("Municipal Services"); foreach(var group in new[]{"Infrastructure > Roads","Infrastructure > Water and Sanitation","Infrastructure > Electricity","Community Services"}) root.Nodes.Add(group); root.Expand(); }
        private void btnFilter_Click(object? s,EventArgs e) => LoadRequests(_service.Search(txtKeyword.Text,cmbStatus.SelectedItem?.ToString(),cmbCategory.SelectedItem?.ToString()));
        private void btnClear_Click(object? s,EventArgs e) { txtKeyword.Clear(); cmbStatus.SelectedIndex=0; cmbCategory.SelectedIndex=0; LoadRequests(_service.GetAll()); }
        private void dgvRequests_CellFormatting(object? s,DataGridViewCellFormattingEventArgs e) { if(e.RowIndex<0) return; var n=dgvRequests.Columns[e.ColumnIndex].Name; if(n=="Priority"||n=="Status") { var v=e.Value?.ToString(); e.CellStyle.ForeColor=v switch { "Critical"=>Color.DarkRed,"High"=>Color.Red,"Medium"=>Color.DarkOrange,"Resolved"=>Color.Green,"InProgress"=>Color.DarkBlue,_=>Color.Black }; e.CellStyle.Font=new Font(dgvRequests.Font,FontStyle.Bold); } }
        private void dgvRequests_CellClick(object? s,DataGridViewCellEventArgs e) { if(e.RowIndex>=0) { var id=dgvRequests.Rows[e.RowIndex].Cells["RequestId"].Value?.ToString(); if(id!=null) ShowRequest(_service.FindById(id)); } }
        private void btnTrack_Click(object? s,EventArgs e) { if(string.IsNullOrWhiteSpace(txtTrackId.Text)) { MessageBox.Show("Enter a request ID such as SR-0001.","Track request",MessageBoxButtons.OK,MessageBoxIcon.Information); return; } var r=_service.FindById(txtTrackId.Text); if(r==null) { txtDetails.Text="No request was found with that ID. Please check the format and try again."; MessageBox.Show(txtDetails.Text,"Request not found",MessageBoxButtons.OK,MessageBoxIcon.Information); return; } ShowRequest(r); }
        private void ShowRequest(ServiceRequest? r) { if(r==null) return; _selected=r; txtTrackId.Text=r.RequestId; txtDetails.Text=$"{r.RequestId}  {r.Title}\r\nCategory: {r.Category}\r\nLocation: {r.Location}\r\nPriority: {r.Priority}\r\nStatus: {r.Status}\r\nDepartment: {r.AssignedDepartment}\r\nSubmitted: {r.SubmittedAt:dd/MM/yyyy}\r\nUpdated: {r.UpdatedAt:dd/MM/yyyy}\r\n\r\nTimeline\r\n"+string.Join("\r\n",r.StatusHistory.Select(h=>$"{h.Timestamp:dd/MM/yyyy HH:mm}  {h.Status}: {h.Note}")); if(tabs.TabPages[0].Controls.Count==1) { var p=tabs.TabPages[0].Controls[0] as Panel; if(p!=null) { p.Controls.Add(txtDetails); txtDetails.Dock=DockStyle.Bottom; txtDetails.Height=145; } } }
        private void btnAdvance_Click(object? s,EventArgs e) { if(_selected==null) { MessageBox.Show("Select or track a request first."); return; } if(_service.AdvanceStatus(_selected)) { LoadRequests(_service.GetAll()); ShowRequest(_selected); txtInsights.Text=_service.Insights(); } else MessageBox.Show("This request is already resolved."); }
        private void btnUrgent_Click(object? s,EventArgs e) { var r=_service.NextUrgent(); if(r==null) { MessageBox.Show("There are no open requests."); return; } ShowRequest(r); MessageBox.Show($"Next urgent request: {r.RequestId} - {r.Title}\r\nPriority: {r.Priority}","Urgent queue"); }
        private void btnProcess_Click(object? s,EventArgs e) { var r=_service.ProcessNext(); if(r==null) { MessageBox.Show("There are no open requests."); return; } LoadRequests(_service.GetAll()); ShowRequest(r); txtInsights.Text=_service.Insights(); }
        private void btnRelated_Click(object? s,EventArgs e) { if(_selected==null) { MessageBox.Show("Select or track a request first."); return; } txtRelated.Text=$"Related cluster for {_selected.RequestId}\r\n\r\nBFS: {string.Join(" -> ",_service.RelatedBfs(_selected))}\r\n\r\nDFS: {string.Join(" -> ",_service.RelatedDfs(_selected))}"; tabs.SelectedIndex=2; }
        private void btnRoute_Click(object? s,EventArgs e) { var p=_service.PlanRoute(); txtRoute.Text=$"Maintenance crew route (Kruskal minimum spanning {(p.IsForest?"forest":"tree")})\r\n\r\n"+string.Join("\r\n",p.Edges.Select(e=>$"{e.From} -> {e.To}: {e.Distance:0} km"))+ $"\r\n\r\nTotal distance: {p.TotalDistance:0} km\r\n{(p.IsForest?"The open-request locations are disconnected, so this is a minimum spanning forest.":"This is the cheapest network connecting all affected locations.")}"; tabs.SelectedIndex=3; }
        private void treeCategories_AfterSelect(object? s,TreeViewEventArgs e) { var text=e.Node.Text; if(text.Contains("Road")) { cmbCategory.SelectedItem="Road"; LoadRequests(_service.Search(null,"All","Road")); } else if(text.Contains("Water")) { cmbCategory.SelectedItem="Water"; LoadRequests(_service.Search(null,"All","Water")); } else if(text.Contains("Electricity")) { cmbCategory.SelectedItem="Electricity"; LoadRequests(_service.Search(null,"All","Electricity")); } }
        private void btnSelfCheck_Click(object? s,EventArgs e) { txtInsights.Text += "\r\n\r\nSelf-check: "+(_service.SelfCheck()?"PASS - AVL sequential insert/search and balance verified.":"FAIL"); }
    }
}
